// 재료명으로 소비기한 자동 조회
function getShelfLife(name) {
  // 직접 매칭
  if(SHELF_LIFE_DB[name]) return SHELF_LIFE_DB[name];
  // 부분 매칭 (예: "닭가슴살볶음" → "닭가슴살")
  for(const key of Object.keys(SHELF_LIFE_DB)) {
    if(name.includes(key)) return SHELF_LIFE_DB[key];
  }
  // 기본값: 냉장 7일
  return {days:7, storage:"냉장"};
}

